from pathlib import Path
import json,gzip,hashlib,collections
ROOT=Path(__file__).parent/'comparison-v1';manifest=json.loads((ROOT/'manifest.json').read_text());models=['ours','meld-v5','meld-v8']
results={m:json.loads((ROOT/m/'results.json').read_text()) for m in models}
inputs=[json.loads(l) for l in gzip.decompress((ROOT/'suite.jsonl.gz').read_bytes()).splitlines()];expected={r['id'] for r in inputs};reference={r['id']:r for r in inputs};pred={};verification={}
for m in models:
 with gzip.open(ROOT/m/'predictions.jsonl.gz','rt') as f:rows=[json.loads(l) for l in f]
 assert len(rows)==len(expected) and {r['id'] for r in rows}==expected
 assert all(r['text_sha256']==reference[r['id']]['text_sha256'] for r in rows)
 pred[m]={r['id']:r for r in rows}
 verification[m]={'rows':len(rows),'input_hashes_match':True,'predictions_sha256':hashlib.sha256((ROOT/m/'predictions.jsonl.gz').read_bytes()).hexdigest(),'thresholds':json.loads((ROOT/m/'thresholds.json').read_text())}
for rid in expected:
 base=pred['ours'][rid]
 for m in models[1:]:
  r=pred[m][rid];assert r['tokens']==base['tokens'] and r['sentences']==base['sentences']
  for f in ['token_counts','sentence_counts']:
   if base[f] is None:assert r[f] is None;continue
   # Exact same positives/negatives evaluated despite different tokenizers.
   a=base[f];b=r[f];assert a[0]+a[2]==b[0]+b[2] and a[1]+a[3]==b[1]+b[3],(rid,m,f)
summary={'rows':len(expected),'datasets':len(manifest['datasets']),'models':{},'verification':verification}
for m,res in results.items():
 d=res['datasets'];summary['models'][m]={'seconds':res['elapsed_seconds'],'v3_target_tokens':d['paper_v3_target']['overall']['span_or_historical_human_token_metrics'],'v3_target_sentences':d['paper_v3_target']['overall']['span_or_historical_human_sentence_metrics'],'novel_clean_human_isolated':d['human_paper_remaining']['novel_clean']['span_or_historical_human_token_metrics'],'novel_clean_human_context':d['human_paper_context']['novel_clean']['span_or_historical_human_token_metrics'],'arena_tokens':d['arena50']['overall']['span_or_historical_human_token_metrics'],'arena_sentences':d['arena50']['overall']['span_or_historical_human_sentence_metrics'],'opai_tokens':d['opai']['overall']['span_or_historical_human_token_metrics'],'opai_sentences':d['opai']['overall']['span_or_historical_human_sentence_metrics']}
(ROOT/'summary.json').write_text(json.dumps(summary,indent=2))
for m,s in summary['models'].items():
 print(m,'seconds',round(s['seconds'],1))
 for k,v in s.items():
  if isinstance(v,dict):print(k,{q:v.get(q) for q in ['precision','recall','human_fpr','groups','units']})
def pct(x):return '—' if x is None else f'{100*x:.2f}%'
def v3(m,kind):
 s=summary['models'][m]['v3_target_'+kind];return pct(s['precision'])+' / '+pct(s['recall'])
lines=['# Three-model comparison','',f"**{len(expected):,} test examples across {len(manifest['datasets'])} groups**, with 1,048 separate validation examples. Same inputs, common reference-token/sentence boundaries, and validation-only 1% human-FPR operating points. No model retraining. All final inference uses BF16; the interrupted FP32 baseline attempt is excluded.",'','| Measure | Our ModernBERT | MELD v5 | MELD v8 |','|---|---:|---:|---:|']
for label,fn in [('v3 target token precision / recall',lambda m:v3(m,'tokens')),('v3 target sentence precision / recall',lambda m:v3(m,'sentences')),('v3 target human token FPR',lambda m:pct(summary['models'][m]['v3_target_tokens']['human_fpr'])),('Untouched clean human: token FPR, isolated',lambda m:pct(summary['models'][m]['novel_clean_human_isolated']['human_fpr'])),('Untouched clean human: token FPR, with neighbors',lambda m:pct(summary['models'][m]['novel_clean_human_context']['human_fpr'])),('50-generator Arena: token recall',lambda m:pct(summary['models'][m]['arena_tokens']['recall'])),('50-generator Arena: sentence recall',lambda m:pct(summary['models'][m]['arena_sentences']['recall'])),('OpAI editing trajectories: token precision / recall',lambda m:pct(summary['models'][m]['opai_tokens']['precision'])+' / '+pct(summary['models'][m]['opai_tokens']['recall']))]:lines.append('| '+label+' | '+' | '.join(fn(m) for m in models)+' |')
lines+=['','## Selection and interpretation','','The earlier full evaluation took 300 seconds plus 100 seconds for the paired human-context supplement. This fixed subset preserves every available categorical label, generator, domain, attack, operation, year, conference and length bucket in each source benchmark. It includes all 390 historical test papers, all 50 Arena generators (20 shared prompts), complete small benchmarks, paired human-context checks and all 1,038 quality-filtered v3 target examples. Selection uses fixed hashes and metadata; no detector score determines inclusion. Twelve examples were added to fill rare metadata gaps before scoring.','','This is a coverage benchmark for repeated comparisons, not a prevalence-weighted estimate of all available text. Sampling fractions differ, and precision depends on each benchmark’s human/AI mix. Individual rare slices can be noisy: Arena has only 20 prompt clusters, and source-group sampling changes OpAI point estimates. Use per-dataset results and the paper/source-group bootstrap intervals in `summary.json` and each model’s `results.json`; do not average all rows into one accuracy number. Confidence intervals treat the chosen suite as sampled clusters and do not correct every stratified sampling fraction.','','The suite has already been inspected and is no longer a blind final holdout. Possible public-benchmark overlap with MELD training is unknown. Paper pilots are explicitly exploratory; synthetic mixed examples are proxies. Historical human labels are supported by pre-2022 provenance, not observed writing histories.','','## Scoring','','Our unchanged epoch-2 checkpoint uses the existing BF16 512-token sliding-window inference. MELD v5/v8 use the exact locally saved release weights, verified by SHA-256, BF16 inference, 2,046 content tokens per window and no overlap. No input is truncated. MELD is evaluated as a localization baseline on raw, unchanged text; this is not its publisher’s normalized-text, capped, top-quartile document-scoring leaderboard protocol.','','All scores are mapped to our ModernBERT reference-token boundaries by character-overlap-weighted averaging, then averaged over the same sentence boundaries. Thus all models have identical human/AI denominators, checked in `summary.json`. Mixed-boundary and ignored regions are masked. Document-only labels are never invented as token/sentence truth. Existing contradictory span annotations are excluded from primary span metrics. Exact duplicate text has one vote within each reported condition.','','Each model’s token and sentence thresholds are selected using the same original 1,048 validation passages, with at most 1% empirical human FPR. Document decisions separately threshold the mean reference-token score at 1% FPR on the 524 validation human originals. This is in-domain historical-paper calibration, not a promise of 1% FPR under domain shift. Our original frozen thresholds are also reported separately in `ours/original-threshold-results.json`. MELD scores are raw evidence, not probabilities, despite the retained machine field name `mean_ai_probability`.','','## Document-label diagnostics','','These use only unambiguous native human/AI document labels and the common validation-calibrated mean-score rule. Mixed and assisted/ambiguous labels are excluded. Human-only / AI-only groups cannot establish both precision and FPR.','','Each cell is **recall / human FPR**. Detailed precision, recall, FPR and AUROC breakdowns are in the JSON reports.','','| Dataset | Our ModernBERT | MELD v5 | MELD v8 |','|---|---:|---:|---:|']
for ds in manifest['datasets']:
 if ds in ['human_paper_context','paper_v3_target']:continue
 cells=[]
 for m in models:
  z=results[m]['datasets'][ds]['overall']['document_native_label_metrics'];cells.append(pct(z['recall'])+' / '+pct(z['human_fpr']))
 lines.append('| '+ds+' | '+' | '.join(cells)+' |')
lines+=['','## Artifacts and timing','','`manifest.json` freezes selection and input hashes. `coverage.json` audits coverage and compares our old-threshold subset estimates with the earlier full suite; it does not tune selection. `summary.json` contains shared-denominator verification and confidence intervals. Each model directory has validation thresholds, per-example predictions and complete breakdowns. Raw reference-token score caches remain on the private A100 Space for future reaggregation.','','| Model | Inference, calibration and score summarization |','|---|---:|']
for m in models:lines.append(f"| {m} | {summary['models'][m]['seconds']:.1f} seconds |")
lines+=['','Times exclude checkpoint transfer, initial failed upstream download, final bootstrap report construction and setup. The full end-to-end log is retained on the Space.']
(ROOT/'README.md').write_text('\n'.join(lines)+'\n')
print('Verified identical row IDs, hashes, token and sentence denominators for all three models.')
